# ─── Performance Tests ──────────────────────────────────────────────────────

class TestPerformance:
    """Validate performance characteristics of state operations."""

    def test_large_state_load_time(self, sample_state):
        """Measure load time for large state files."""
        import time
        
        # Create a large state by duplicating cards
        large_state = deepcopy(sample_state)
        base_cards = deepcopy(sample_state["cards"])
        
        for i in range(100):  # Simulate 100x card count
            for card in base_cards:
                new_card = deepcopy(card)
                new_card["card_id"] = f"{card['card_id']}-copy-{i}"
                large_state["cards"].append(new_card)
        
        # Measure serialization time
        start_time = time.time()
        json_str = json.dumps(large_state)
        serialization_time = time.time() - start_time
        
        # Measure deserialization time
        start_time = time.time()
        json.loads(json_str)
        deserialization_time = time.time() - start_time
        
        # Assert reasonable performance (adjust thresholds as needed)
        assert serialization_time < 1.0, f"Serialization too slow: {serialization_time}s"
        assert deserialization_time < 1.0, f"Deserialization too slow: {deserialization_time}s"

    def test_memory_usage(self, sample_state):
        """Estimate memory usage of state object."""
        import sys
        
        state_size = sys.getsizeof(sample_state)
        json_size = len(json.dumps(sample_state))
        
        # Log sizes for monitoring
        print(f"\nState object size: {state_size} bytes")
        print(f"JSON string size: {json_size} bytes")
        
        # Assert reasonable size (adjust as needed)
        assert json_size < 10 * 1024 * 1024, "State JSON exceeds 10MB limit"


