class TestProperties:
    """Property-based tests for invariant validation."""

    def test_card_id_uniqueness_property(self, sample_state):
        """Property: All card IDs must be unique."""
        card_ids = [card["card_id"] for card in sample_state["cards"]]
        assert len(card_ids) == len(set(card_ids)), "Card ID uniqueness violated"

    def test_timestamp_monotonicity_property(self, sample_state):
        """Property: Timestamps must be monotonically increasing."""
        for card in sample_state["cards"]:
            timestamps = [
                datetime.fromisoformat(card["created_at"]),
                datetime.fromisoformat(card["updated_at"])
            ]
            if card["completed_at"]:
                timestamps.append(datetime.fromisoformat(card["completed_at"]))
            
            for i in range(len(timestamps) - 1):
                assert timestamps[i] <= timestamps[i + 1], \
                    f"Timestamp monotonicity violated for card '{card['card_id']}'"

    def test_status_invariants_property(self, sample_state):
        """Property: Card status must always be valid."""
        for card in sample_state["cards"]:
            assert card["status"] in VALID_STATUSES, \
                f"Invalid status '{card['status']}' for card '{card['card_id']}'"


